import java.util.*;
import java.io.*;

public class Main {
    static int n, t, rx, ry;
    static String[] lab = new String[20], sci = new String[20];
    static int[][][][][] mem = new int[12][12][12][12][62];
    static int[][] cap = new int[250][250], par = new int[250];
    static int[][] dist = new int[20][20], vis = new int[20][20];
    static int[] dx = {1, -1, 0, 0};
    static int[] dy = {0, 0, 1, -1};
    static boolean[][] goodMap;

    static boolean good(int x, int y) {
        if (x < 0 || x >= n || y < 0 || y >= n) return false;
        return lab[x].charAt(y) != 'Y' && lab[x].charAt(y) != 'Z';
    }

    static void pre() {
        for (int i = 0; i < n; i++) {
            Arrays.fill(dist[i], Integer.MAX_VALUE);
            Arrays.fill(vis[i], 0);
        }
        dist[rx][ry] = 0;
        vis[rx][ry] = 1;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{rx, ry});
        while (!q.isEmpty()) {
            int[] curr = q.poll();
            int x = curr[0], y = curr[1];
            for (int k = 0; k < 4; k++) {
                int nx = x + dx[k];
                int ny = y + dy[k];
                if (nx >= 0 && nx < n && ny >= 0 && ny < n && good(nx, ny) && vis[nx][ny] == 0) {
                    dist[nx][ny] = dist[x][y] + 1;
                    vis[nx][ny] = 1;
                    q.offer(new int[]{nx, ny});
                }
            }
        }
    }

    static boolean dfs(int x0, int y0, int x1, int y1, int ptr, int[][][][][] mem, int[][] dist) {
        if (ptr > t) return false;
        int ret = mem[x0][y0][x1][y1][ptr];
        if (ret != -1) return ret == 1;
        if (x0 == x1 && y0 == y1) return dist[x0][y0] >= ptr;
        if (dist[x0][y0] <= ptr) return false;
        for (int k = 0; k < 4; k++) {
            int nx = x0 + dx[k];
            int ny = y0 + dy[k];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && good(nx, ny)) {
                if (dfs(nx, ny, x1, y1, ptr + 1, mem, dist)) {
                    return true;
                }
            }
        }
        return false;
    }

    static boolean fml(int s, int t, int[][] cap, int[] par) {
        Arrays.fill(par, -1);
        par[s] = -2;
        Queue<Integer> qu = new LinkedList<>();
        qu.offer(s);
        while (!qu.isEmpty()) {
            int v = qu.poll();
            for (int i = s; i <= t; i++) {
                if (par[i] == -1 && cap[v][i] > 0) {
                    par[i] = v;
                    qu.offer(i);
                }
            }
        }
        return par[t] != -1;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        n = Integer.parseInt(parts[0]);
        t = Integer.parseInt(parts[1]);
        for (int i = 0; i < n; i++) {
            sci[i] = br.readLine();
        }
        for (int i = 0; i < n; i++) {
            lab[i] = br.readLine();
        }
        List<int[]> pos = new ArrayList<>();
        List<Integer> lc = new ArrayList<>();
        List<Integer> sc = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char c = sci[i].charAt(j);
                if (c == 'Z') {
                    rx = i;
                    ry = j;
                } else if (c >= '0' && c <= '9') {
                    pos.add(new int[]{i, j});
                    lc.add(lab[i].charAt(j) - '0');
                    sc.add(c - '0');
                }
            }
        }
        int m = pos.size();
        for (int[] row : cap) {
            Arrays.fill(row, 0);
        }
        for (int[] row : mem) {
            for (int[][][] a : row) {
                for (int[][] b : a) {
                    for (int[] c : b) {
                        Arrays.fill(c, -1);
                    }
                }
            }
        }
        for (int i = 0; i < m; i++) {
            cap[0][i + 1] = sc.get(i);
            cap[m + 1 + i][2 * m + 1] = lc.get(i);
        }
        pre();

        // Initialize mem array
        for (int x0 = 0; x0 <= 11; x0++) {
            for (int y0 = 0; y0 <= 11; y0++) {
                for (int x1 = 0; x1 <= 11; x1++) {
                    for (int y1 = 0; y1 <= 11; y1++) {
                        Arrays.fill(mem[x0][y0][x1][y1], -1);
                    }
                }
            }
        }
        int[][][][][] memRef = new int[12][12][12][12][62];
        for (int i = 0; i <= 11; i++) {
            for (int j = 0; j <= 11; j++) {
                for (int m0 = 0; m0 <= 11; m0++) {
                    for (int m1 = 0; m1 <= 11; m1++) {
                        Arrays.fill(memRef[i][j][m0][m1], -1);
                    }
                }
            }
        }
        int flow = 0;
        while (fml(0, 2 * m + 1, cap, par)) {
            int temp = 2 * m + 1;
            int nflow = Integer.MAX_VALUE;
            while (temp >= 0 && par[temp] >= 0) {
                nflow = Math.min(nflow, cap[par[temp]][temp]);
                temp = par[temp];
            }
            temp = 2 * m + 1;
            while (temp >= 0 && par[temp] >= 0) {
                cap[par[temp]][temp] -= nflow;
                cap[temp][par[temp]] += nflow;
                temp = par[temp];
            }
            flow += nflow;
        }

        System.out.println(flow);
    }
}

